  --clr-text:      #1a1917;
  --clr-muted:     #6b6860;
  --clr-accent:    #4f46e5;
  --clr-accent-lt: #ede9fe;
  --clr-focus-ring:#4f46e5;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --shadow-card: 0 1px 3px rgba(0,0,0,.06), 0 4px 12px rgba(0,0,0,.04);
  --shadow-hover: 0 2px 6px rgba(0,0,0,.08), 0 8px 24px rgba(0,0,0,.06);

  --transition: 150ms ease;
}

/* ── Base ───────────────────────────────────────────────────────── */
html { scroll-behavior: smooth; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Skip link ──────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--clr-accent);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ── Header ─────────────────────────────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.header-inner {
  max-width: 780px;
  margin: 0 auto;
  padding: .875rem 1.5rem;
  display: flex;
  align-items: center;
  gap: .625rem;
}
.logo { font-size: 1.4rem; }
.site-name {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: -.01em;
  color: var(--clr-text);
}

/* ── Hero ───────────────────────────────────────────────────────── */
.hero {
  max-width: 780px;
  margin: 0 auto;
  padding: 3.5rem 1.5rem 2rem;
  text-align: center;
}
.hero h1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
}
.hero-sub {
  margin-top: .625rem;
  color: var(--clr-muted);
  font-size: 1.05rem;
}

/* ── FAQ container ──────────────────────────────────────────────── */
.faq-container {
  max-width: 780px;
  margin: 0 auto;
  padding: 0 1.5rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

/* ── Section ────────────────────────────────────────────────────── */
.faq-section {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.section-label {
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--clr-accent);
  margin-bottom: .25rem;
}

/* ── Disclosure card (.example) ─────────────────────────────────── */
.example {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.example:hover {
  box-shadow: var(--shadow-hover);
  border-color: #d0cec8;
}

/* ── Trigger ────────────────────────────────────────────────────── */
.example h3 { font-size: 1rem; /* resets UA bold size */ }

.example h3 button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  padding: 1.125rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--clr-text);
  line-height: 1.4;
  transition: background var(--transition), color var(--transition);
}
.example h3 button:hover {
  background: #faf9f7;
  color: var(--clr-accent);
}
.example h3 button:focus-visible {
  outline: 2px solid var(--clr-focus-ring);
  outline-offset: -2px;
  border-radius: var(--radius-sm);
}

/* ── Chevron icon ───────────────────────────────────────────────── */
.chevron {
  flex-shrink: 0;
  color: var(--clr-muted);
  transition: transform 250ms ease, color var(--transition);
}
.example h3 button[aria-expanded="true"]  .chevron { transform: rotate(180deg); color: var(--clr-accent); }
.example h3 button[aria-expanded="false"] .chevron { transform: rotate(0deg); }
.example h3 button:hover .chevron { color: var(--clr-accent); }

/* ── Panel ──────────────────────────────────────────────────────── */
.details {
  padding: 0 1.25rem 1.25rem;
  border-top: 1px solid var(--clr-border);
  animation: slide-in 200ms ease forwards;
}
.details p {
  color: var(--clr-muted);
  font-size: .9375rem;
  line-height: 1.7;
  padding-top: 1rem;
}

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Footer ─────────────────────────────────────────────────────── */
.site-footer {
  text-align: center;
  padding: 1.5rem;
  border-top: 1px solid var(--clr-border);
  color: var(--clr-muted);
  font-size: .85rem;
}

/* ── Reduced motion ─────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0ms !important; transition-duration: 0ms !important; }
}

/* ── Forced colours (Windows High Contrast) ─────────────────────── */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h3 button { forced-color-adjust: auto; }
  .chevron { stroke: ButtonText; }
}

/* ── Reflow — narrow viewport ───────────────────────────────────── */
@media (max-width: 480px) {
  .example h3 button { padding: 1rem; font-size: .9375rem; }
  .details { padding: 0 1rem 1rem; }
  .hero { padding: 2.25rem 1rem 1.5rem; }
  .faq-container { padding: 0 1rem 3rem; }
}
