+  font-size: .7rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--clr-accent);
+  margin-bottom: .25rem;
+}
+
+/* ── Disclosure card (.example) ─────────────────────────────────── */
+.example {
+  background: var(--clr-surface);
+  border: 1px solid var(--clr-border);
+  border-radius: var(--radius-md);
+  box-shadow: var(--shadow-card);
+  overflow: hidden;
+  transition: box-shadow var(--transition), border-color var(--transition);
+}
+.example:hover {
+  box-shadow: var(--shadow-hover);
+  border-color: #d0cec8;
+}
+
+/* ── Trigger ────────────────────────────────────────────────────── */
+.example h3 { font-size: 1rem; /* resets UA bold size */ }
+
+.example h3 button {
+  width: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  background: none;
+  border: none;
