+  color: var(--clr-text);
+  line-height: 1.4;
+  transition: background var(--transition), color var(--transition);
+}
+.example h3 button:hover {
+  background: #faf9f7;
+  color: var(--clr-accent);
+}
+.example h3 button:focus-visible {
+  outline: 2px solid var(--clr-focus-ring);
+  outline-offset: -2px;
+  border-radius: var(--radius-sm);
+}
+
+/* ── Chevron icon ───────────────────────────────────────────────── */
+.chevron {
+  flex-shrink: 0;
+  color: var(--clr-muted);
