+}
+.example h3 button[aria-expanded="true"]  .chevron { transform: rotate(180deg); color: var(--clr-accent); }
+.example h3 button[aria-expanded="false"] .chevron { transform: rotate(0deg); }
+.example h3 button:hover .chevron { color: var(--clr-accent); }
+
+/* ── Panel ──────────────────────────────────────────────────────── */
+.details {
+  padding: 0 1.25rem 1.25rem;
+  border-top: 1px solid var(--clr-border);
+  animation: slide-in 200ms ease forwards;
+}
+.details p {
