    const r2 = await page.evaluate(() => window.axe.run().then(function(r){ return r; }));

    await b.close();

    function fmt(v){ return {id:v.id, impact:v.impact, targets:v.nodes.map(function(n){ return n.target; })}; }
    function filterWcag(violations){ return violations.filter(function(v){ return v.tags.indexOf('best-practice') === -1; }); }
    function filterBp(violations){ return violations.filter(function(v){ return v.tags.indexOf('best-practice') !== -1; }); }

    const result = {
      collapsed: { wcag: filterWcag(r1.violations).map(fmt), bp: filterBp(r1.violations).map(fmt) },
      expanded:  { wcag: filterWcag(r2.violations).map(fmt), bp: filterBp(r2.violations).map(fmt) }
    };
    process.stdout.write(JSON.stringify(result, null, 2));
    const totalWcag = result.collapsed.wcag.length + result.expanded.wcag.length;
    process.exit(totalWcag ? 1 : 0);
  } catch(e) { process.stderr.write(e.message + '\n' + e.stack); process.exit(2); }
})();
